static void toolText(const char *text,float x,float y,float size,SDL_Color colour,int width){if(ZMenuTheme::queueText(text,x,y,size,colour,width))return;auto *surface=ZSDL_Surface::GetMainSoftwareSurface();auto *image=ZMenuTheme::text(text,size,colour);if(surface&&image){SDL_Rect source{0,0,std::min(width,image->w),image->h},destination{(int)x,(int)y,source.w,source.h};SDL_BlitSurface(image,&source,surface,&destination);}SDL_DestroySurface(image);}
static bool sameOrders(const vector<waypoint> &a,const vector<waypoint> &b){if(a.size()!=b.size())return false;for(size_t i=0;i<a.size();++i)if(a[i].mode!=b[i].mode||a[i].ref_id!=b[i].ref_id||a[i].x!=b[i].x||a[i].y!=b[i].y||a[i].attack_to!=b[i].attack_to)return false;return true;}

void ZPlayer::BattleEventLog(const string &kind,const string &text,int amount){if(replay_seeking)return;int second=(int)MatchElapsed();if(!battle_timeline.empty()){auto &last=battle_timeline.back();if(last.kind==kind&&second-last.second<2){last.amount+=amount;last.text=text.substr(0,100);return;}}if(battle_timeline.size()>=256)battle_timeline.erase(battle_timeline.begin());battle_timeline.push_back({second,kind,text.substr(0,100),amount});}
void ZPlayer::ReceiveBattleTool(const string &packet){
 std::istringstream input(packet);string kind;std::getline(input,kind,'|');
 if(kind=="@session"){string seed;std::getline(input,session_campaign,'|');std::getline(input,session_mission,'|');std::getline(input,seed,'|');std::getline(input,session_campaign_version);if(session_campaign.size()>64||session_mission.size()>64||session_campaign_version.size()>32||seed.empty()||seed.size()>10)return;char *end=nullptr;unsigned long parsed=strtoul(seed.c_str(),&end,10);if(!end||*end)return;recorded_seed=parsed;if(!replay_active&&!session_campaign.empty()&&session_campaign!="original")frontend.ResumeSavedCampaign(game_map_name,session_campaign,-1,session_mission);BattleEventLog("start","Mission started");return;}
 if(kind=="@checkpoint"){string title;std::getline(input,title);BattleFeedback("Checkpoint saved: "+title.substr(0,100));BattleEventLog("checkpoint",title);return;}
 if(kind!="@dialogue"||replay_seeking)return;Dialogue entry;string duration;std::getline(input,entry.speaker,'|');std::getline(input,entry.character,'|');std::getline(input,duration,'|');std::getline(input,entry.text);if(entry.speaker.size()>64||entry.character.size()>32||entry.text.empty()||entry.text.size()>512||duration.empty()||duration.size()>2)return;for(char c:duration)if(c<'0'||c>'9')return;entry.seconds=atoi(duration.c_str());if(entry.seconds<1||entry.seconds>60)return;if(dialogue_history.size()>=32)dialogue_history.erase(dialogue_history.begin());dialogue_history.push_back(entry);if(dialogue_queue.size()<16){bool first=dialogue_queue.empty();dialogue_queue.push_back(entry);if(first)StartDialogue();}BattleEventLog("dialogue",entry.speaker+": "+entry.text);
}
void ZPlayer::StartDialogue(){dialogue_started=SDL_GetTicks();dialogue_page=0;if(dialogue_queue.empty()||!graphics_loaded)return;auto &entry=dialogue_queue.front();ZPortrait::Init();dialogue_portrait.SetRobotID(GRUNT);for(int i=0;i<MAX_ROBOT_TYPES;++i)if(robot_type_string[i]==entry.character)dialogue_portrait.SetRobotID(i);dialogue_portrait.SetTeam(our_team);dialogue_portrait.SetTerrainType((planet_type)zmap.GetMapBasics().terrain_type);dialogue_portrait.SetOverMap(false);dialogue_portrait.SetDoRandomAnims(!zod_reduced_motion);dialogue_portrait.StartAnim(UNIT_REPORTING1_ANIM,false);}
void ZPlayer::SkipDialogue(){if(!dialogue_queue.empty())dialogue_queue.erase(dialogue_queue.begin());StartDialogue();}
bool ZPlayer::CheckpointAvailable()const{if(replay_active||!(remote_address=="127.0.0.1"||remote_address=="localhost"))return false;ZSaveInfo info;if(!ZSave_ReadInfo(ZSAVE_CHECKPOINT_SLOT,info))return false;return !session_mission.empty()?info.campaign_id==session_campaign&&info.mission_uid==session_mission:info.map_name==game_map_name;}
void ZPlayer::RetryCheckpoint(){if(!CheckpointAvailable()){BattleFeedback("No checkpoint for this mission");return;}show_match_summary=false;summary_continue_sent=true;frontend.LoadCheckpoint();}
void ZPlayer::RenderBattleTools(){
 auto *surface=ZSDL_Surface::GetMainSoftwareSurface();if(!surface)return;if(!replay_active&&!orders_open){const char *labels[]={"Order queue","Bug report","Retry checkpoint","Replay dialogue"};for(int i=0;i<4;++i){if(i==0&&select_info.selected_list.size()!=1)continue;if(i==2&&!CheckpointAvailable())continue;if(i==3&&dialogue_history.empty())continue;int x=8+i*146;ZMenuTheme::rect(surface,x,44,140,28,35,48,59);toolText(labels[i],x+6,51,11,{245,220,170,255},128);}}
 if(orders_open)RenderOrders();if(dialogue_queue.empty())return;auto &entry=dialogue_queue.front();int width=std::min(580,init_w-116),x=8,y=init_h-224;int font=std::max(10,12*zod_subtitle_percent/100),columns=std::max(16,(width-112)/(font/2+1));vector<string> lines;std::istringstream words(entry.text);string word,line;while(words>>word){while((int)word.size()>columns){if(!line.empty()){lines.push_back(line);line.clear();}lines.push_back(word.substr(0,columns));word.erase(0,columns);}if(!line.empty()&&(int)(line.size()+word.size()+1)>columns){lines.push_back(line);line.clear();}if(!line.empty())line+=' ';line+=word;}if(!line.empty())lines.push_back(line);int rows=std::max(2,128/(font+3)),pages=std::max(1,((int)lines.size()+rows-1)/rows);if(SDL_GetTicks()-dialogue_started>(Uint64)entry.seconds*1000){if(dialogue_page+1<pages){++dialogue_page;dialogue_started=SDL_GetTicks();}else {SkipDialogue();return;}}
 if(zod_subtitle_background)ZMenuTheme::panel(surface,x,y,width,180);toolText(entry.speaker.c_str(),x+100,y+8,14,{255,200,100,255},width-112);if(graphics_loaded){dialogue_portrait.SetCords(x+6,y+28);if(!zod_reduced_motion){if(!dialogue_portrait.DoingAnim())dialogue_portrait.StartAnim(UNIT_REPORTING1_ANIM,false);dialogue_portrait.Process();}dialogue_portrait.DoRender();}else toolText(entry.character.c_str(),x+6,y+38,11,{200,200,210,255},86);
 for(int i=0;i<rows&&dialogue_page*rows+i<(int)lines.size();++i)toolText(lines[dialogue_page*rows+i].c_str(),x+100,y+30+i*(font+3),font,{245,245,245,255},width-112);ZMenuTheme::rect(surface,x+100,y+150,120,24,40,55,65);toolText("Skip dialogue",x+106,y+155,11,{255,220,130,255},108);if(pages>1){string page=to_string(dialogue_page+1)+"/"+to_string(pages);toolText(page.c_str(),x+240,y+155,11,{255,220,130,255},80);}
}
void ZPlayer::RenderOrders(){auto *surface=ZSDL_Surface::GetMainSoftwareSurface();int width=std::min(440,init_w-116);ZMenuTheme::panel(surface,8,42,width,330);toolText("ORDER QUEUE / planned links; Apply sends to server",18,50,13,{255,210,120,255},width-20);int start=order_choice/6*6;for(int row=0;row<6&&start+row<(int)edited_orders.size();++row){int index=start+row;auto &order=edited_orders[index];ZMenuTheme::rect(surface,16,84+row*27,width-16,24,index==order_choice?62:26,45,58);string label=to_string(index+1)+". "+(order.mode==MOVE_WP?string("Move"):order.mode==ATTACK_WP?string("Attack"):"Command "+to_string(order.mode))+" / "+to_string(order.x)+", "+to_string(order.y);toolText(label.c_str(),22,88+row*27,11,{240,240,245,255},width-28);}const char *labels[]={"Up","Down","Remove","Earlier","Later","Apply","Cancel"};for(int i=0;i<7;++i){int x=16+i%3*132,y=258+i/3*34;ZMenuTheme::rect(surface,x,y,124,28,40,55,65);toolText(labels[i],x+6,y+7,11,{245,220,170,255},112);}int sx,sy;zmap.GetViewShift(sx,sy);auto *selected=GetObjectFromID(edited_order_ref,object_list);int lastX=0,lastY=0;if(selected)selected->GetCenterCords(lastX,lastY);for(auto &order:edited_orders){int dx=order.x-lastX,dy=order.y-lastY,steps=std::max(1,std::min(2048,std::max(std::abs(dx),std::abs(dy))));for(int step=0;step<=steps;step+=3){int px=lastX+dx*(double)step/steps-sx,py=lastY+dy*(double)step/steps-sy;if(px>=0&&py>=0&&px<init_w-110&&py<init_h-36)ZMenuTheme::rect(surface,px,py,2,2,130,180,210);}lastX=order.x;lastY=order.y;}for(size_t i=0;i<edited_orders.size();++i){int x=edited_orders[i].x-sx,y=edited_orders[i].y-sy;if(x<0||y<0||x>=init_w-110||y>=init_h-36)continue;ZMenuTheme::rect(surface,x-3,y-3,6,6,244,190,60);auto number=to_string(i+1);toolText(number.c_str(),x+4,y-5,11,{255,240,130,255},32);}}
void ZPlayer::RenderDebriefButton(){auto *surface=ZSDL_Surface::GetMainSoftwareSurface();ZMenuTheme::panel(surface,init_w-190,10,180,28);toolText("Battle debrief",init_w-180,16,12,{255,220,130,255},160);}
void ZPlayer::RenderDebrief(){auto *surface=ZSDL_Surface::GetMainSoftwareSurface();ZMenuTheme::panel(surface,8,8,init_w-16,init_h-16);toolText("MISSION DEBRIEF",20,16,16,{255,210,120,255},init_w-40);string title="Produced "+to_string(battle_produced)+" / damage received "+to_string(battle_damage)+" / captures "+to_string(match_zones_captured)+" / losses "+to_string(match_units_lost);toolText(title.c_str(),20,42,12,{255,210,120,255},init_w-40);int rows=std::max(1,(init_h-145)/28);debrief_scroll=std::max(0,std::min(debrief_scroll,std::max(0,(int)battle_timeline.size()-rows)));for(int row=0;row<rows&&row+debrief_scroll<(int)battle_timeline.size();++row){auto &event=battle_timeline[row+debrief_scroll];string text=to_string(event.second)+"s / "+event.kind+" / "+event.text+(event.amount?" / "+to_string(event.amount):"");toolText(text.c_str(),20,76+row*28,12,{230,235,240,255},init_w-40);}const char *labels[]={"Earlier","Later","Export report","Back"};for(int i=0;i<4;++i){ZMenuTheme::rect(surface,16+i*144,init_h-48,136,28,40,55,65);toolText(labels[i],22+i*144,init_h-41,11,{255,220,130,255},124);}}
bool ZPlayer::BattleToolsClick(int x,int y){
 if(!gui_menu_list.empty())return false;if(debrief_open){if(y>=init_h-48&&y<init_h-20&&x>=16&&x<592){int button=(x-16)/144;if(button==0)debrief_scroll=std::max(0,debrief_scroll-6);if(button==1)debrief_scroll=std::min(std::max(0,(int)battle_timeline.size()-1),debrief_scroll+6);if(button==2)ExportBugBundle();if(button==3)debrief_open=false;}return true;}
 if(show_match_summary&&x>=init_w-190&&y>=10&&y<38){debrief_open=true;return true;}if(orders_open){if(y>=84&&y<246){order_choice=std::min(std::max(0,(int)edited_orders.size()-1),order_choice/6*6+(y-84)/27);return true;}if(y>=258&&y<354&&x>=16&&x<412){int action=(y-258)/34*3+(x-16)/132;if(action==0&&order_choice>0){swap(edited_orders[order_choice],edited_orders[order_choice-1]);--order_choice;}if(action==1&&order_choice+1<(int)edited_orders.size()){swap(edited_orders[order_choice],edited_orders[order_choice+1]);++order_choice;}if(action==2&&!edited_orders.empty()){edited_orders.erase(edited_orders.begin()+order_choice);order_choice=std::max(0,std::min(order_choice,(int)edited_orders.size()-1));}if(action==3)order_choice=std::max(0,order_choice-6);if(action==4)order_choice=std::min(std::max(0,(int)edited_orders.size()-1),order_choice+6);if(action==5){auto *object=GetObjectFromID(edited_order_ref,object_list);if(object&&object->GetOwner()==our_team&&!object->IsDestroyed()&&!replay_active){if(!sameOrders(object->GetWayPointList(),original_orders)){BattleFeedback("Orders changed while editing. Reopen the queue to edit current orders.");orders_open=false;return true;}object->GetWayPointDevList()=edited_orders;SendDevWayPointsOfObj(object);}orders_open=false;}if(action==6)orders_open=false;}return true;}
 if(!dialogue_queue.empty()){int y0=init_h-224;if(x>=108&&x<228&&y>=y0+150&&y<y0+174){SkipDialogue();return true;}}
 if(!replay_active&&!show_match_summary&&y>=44&&y<72&&x>=8&&x<592){int action=(x-8)/146;if(action==0&&select_info.selected_list.size()==1){auto *object=select_info.selected_list[0];if(object->GetOwner()==our_team&&!object->IsDestroyed()){edited_order_ref=object->GetRefID();original_orders=edited_orders=object->GetWayPointList();if(edited_orders.size()>64)edited_orders.resize(64);order_choice=0;orders_open=true;}}if(action==1)ExportBugBundle();if(action==2)RetryCheckpoint();if(action==3&&!dialogue_history.empty()){dialogue_queue.insert(dialogue_queue.begin(),dialogue_history.back());StartDialogue();}return true;}return false;
}

void ZPlayer::ExportBugBundle(){
 std::ostringstream context;context<<"zod-enhanced reproducibility bundle\nEngine: "<<ZOD_VERSION<<"\nBuild: "<<ZBuild_ID()<<"\nCampaign: "<<session_campaign<<"\nCampaign version: "<<session_campaign_version<<"\nMission UID: "<<session_mission<<"\nMap: "<<zmap.GetMapBasics().map_name<<"\nSeed: "<<recorded_seed<<"\nGame speed: "<<zod_game_speed<<"\nDifficulty: "<<zod_bot_difficulty<<"\nUnit limit: "<<zod_max_units_per_team<<"\nMenu scale: "<<zod_menu_scale<<"\nPicture mode: "<<zod_picture_mode<<"\n"<<ZPerf_Report();for(auto &event:battle_timeline)context<<event.second<<"s / "<<event.kind<<" / "<<event.text<<" / "<<event.amount<<"\n";auto text=context.str();vector<pair<string,vector<unsigned char>>> files={{"context.txt",vector<unsigned char>(text.begin(),text.end())}};
 auto attach=[&](const string &name,const string &path){SDL_PathInfo info;if(!SDL_GetPathInfo(path.c_str(),&info)||info.size>128*1024*1024)return;std::ifstream input(path,std::ios::binary);vector<unsigned char> bytes((std::istreambuf_iterator<char>(input)),{});if(input.good()||input.eof())files.push_back({name,std::move(bytes)});};ZSaveInfo save;if(ZSave_ReadInfo(ZSAVE_CHECKPOINT_SLOT,save)&&CheckpointAvailable())attach("checkpoint.save",ZSave_Path(ZSAVE_CHECKPOINT_SLOT));if(ZSave_ReadInfo(0,save)&&((!session_mission.empty()&&save.mission_uid==session_mission&&save.campaign_id==session_campaign)||(session_mission.empty()&&save.map_name==game_map_name)))attach("autosave.save",ZSave_Path(0));
 string replayFolder=ZAsset_Profile()+"replays";int count=0;char **paths=SDL_GlobDirectory(replayFolder.c_str(),"*.zreplay",0,&count);vector<string> names;for(int i=0;paths&&i<count&&i<512;++i)names.push_back(paths[i]);SDL_free(paths);std::sort(names.rbegin(),names.rend());for(auto &name:names){string path,error;if(!ZCampaign_SafeAsset(replayFolder,name,path))continue;ZReplayTape tape;if(tape.Load(path,error)&&tape.mapName==zmap.GetMapBasics().map_name){attach("battle.zreplay",path);break;}}
 string settingsPath=ZAsset_Profile()+"diagnostics/settings-"+to_string(SDL_GetTicksNS())+".txt";SDL_CreateDirectory((ZAsset_Profile()+"diagnostics").c_str());if(zsettings.SaveSettings(settingsPath)){attach("unit-settings.txt",settingsPath);SDL_RemovePath(settingsPath.c_str());}string diagnostics;if(ZAsset_ExportDiagnostics(diagnostics,"idle"))attach("diagnostics.txt",diagnostics);string folder=ZAsset_Profile()+"diagnostics";SDL_CreateDirectory(folder.c_str());string output=folder+"/bug-"+to_string(SDL_GetTicksNS())+".zip",error;if(ZContent_WriteBundle(files,output,error)){BattleFeedback("Bug report bundle saved locally in diagnostics");SDL_OpenURL(("file://"+folder).c_str());}else BattleFeedback(error);
}
